from rest_framework.viewsets import ModelViewSet
from rest_framework.decorators import action
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework_csv.renderers import CSVRenderer
from .models import CustomerProfile
from .serializers import CustomerProfileSerializer

class CustomerProfileViewSet(ModelViewSet):
    permission_classes = [IsAuthenticated]
    serializer_class = CustomerProfileSerializer

    def get_queryset(self):
        return CustomerProfile.objects.filter(tenant=self.request.user.tenant)

    @action(detail=False, methods=['get'], renderer_classes=[CSVRenderer], url_path='export-csv')
    def export_csv(self, request):
        allowed_export_fields = {'id', 'email', 'full_name', 'phone_number'}
        requested_fields = [f.strip() for f in request.query_params.get('fields', 'id,email,full_name').split(',')]
        safe_fields = [f for f in requested_fields if f in allowed_export_fields]

        # Ensure export relies strictly on the tenant-scoped get_queryset()
        data = list(self.get_queryset().values(*safe_fields))
        return Response(data)
